package com.kaipai.service.card.impl;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.kaipai.common.exception.BizException; import com.kaipai.common.result.PageResult; import com.kaipai.mapper.card.*; import com.kaipai.model.card.dto.*; import com.kaipai.model.card.entity.*; import com.kaipai.service.card.ShareCardFavoriteService; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.dao.DuplicateKeyException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class ShareCardFavoriteServiceImpl implements ShareCardFavoriteService { private final ShareCardFavoriteMapper favoriteMapper; private final UserShareCardMapper cardMapper;
 private ShareCardFavorite find(Long u,Long c){return favoriteMapper.selectOne(new LambdaQueryWrapper<ShareCardFavorite>().eq(ShareCardFavorite::getUserId,u).eq(ShareCardFavorite::getShareCardId,c).last("limit 1"));}
 public PageResult<ShareCardFavoriteItemDTO> list(Long u,int page,int size){List<ShareCardFavorite> favorites=favoriteMapper.selectList(new LambdaQueryWrapper<ShareCardFavorite>().eq(ShareCardFavorite::getUserId,u).orderByDesc(ShareCardFavorite::getFavoriteId));if(favorites.isEmpty())return PageResult.empty();List<Long> ids=favorites.stream().map(ShareCardFavorite::getShareCardId).toList();List<UserShareCard> cards=cardMapper.selectList(new LambdaQueryWrapper<UserShareCard>().in(UserShareCard::getShareCardId,ids).eq(UserShareCard::getShareStatus,"active"));Map<Long,UserShareCard> byId=new HashMap<>();for(UserShareCard c:cards)byId.put(c.getShareCardId(),c);List<ShareCardFavoriteItemDTO> active=new ArrayList<>();for(ShareCardFavorite f:favorites){UserShareCard c=byId.get(f.getShareCardId());if(c!=null){ShareCardFavoriteItemDTO d=new ShareCardFavoriteItemDTO();d.setShareCardId(c.getShareCardId());d.setOwnerUserId(c.getUserId());active.add(d);}}int pageNo=Math.max(1,page),pageSize=size<=0?10:Math.min(size,50),from=Math.min(active.size(),(pageNo-1)*pageSize),to=Math.min(active.size(),from+pageSize);return new PageResult<>(active.size(),active.subList(from,to));}
 @Transactional public ShareCardFavoriteStateDTO add(Long u,Long c){UserShareCard card=cardMapper.selectOne(new LambdaQueryWrapper<UserShareCard>().eq(UserShareCard::getShareCardId,c).eq(UserShareCard::getShareStatus,"active").last("limit 1"));if(card==null)throw new BizException("分享卡不存在或已失效");if(u.equals(card.getUserId()))throw new BizException("不能收藏自己的分享卡");if(find(u,c)==null){ShareCardFavorite f=new ShareCardFavorite();f.setUserId(u);f.setShareCardId(c);try{favoriteMapper.insert(f);}catch(DuplicateKeyException ignored){/* concurrent idempotent add */}}return new ShareCardFavoriteStateDTO(true);}
 @Transactional public ShareCardFavoriteStateDTO remove(Long u,Long c){ShareCardFavorite f=find(u,c);if(f!=null)favoriteMapper.deleteById(f.getFavoriteId());return new ShareCardFavoriteStateDTO(false);}
}
